import{_ as r,o,c as n,ag as s}from"./chunks/framework.C9sp7nFj.js";const a="/images/blend-types-comparison.png",_=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"过渡类型.md","filePath":"过渡类型.md","lastUpdated":1778862643000}'),e={name:"过渡类型.md"};function l(d,t,i,g,h,c){return o(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="default-默认" tabindex="-1">DEFAULT 默认 <a class="header-anchor" href="#default-默认" aria-label="Permalink to &quot;DEFAULT 默认&quot;">​</a></h2><p>通常这是一个全局预设值。</p><ul><li><strong>动作逻辑：</strong> 它是系统参数中设定的默认过渡方式（通常厂家默认会带一点圆滑，或者直接指向 FINE）。</li><li><strong>路径特点：</strong> 取决于系统后台的配置。</li></ul><h2 id="fine-精确定位" tabindex="-1">FINE (精确定位) <a class="header-anchor" href="#fine-精确定位" aria-label="Permalink to &quot;FINE (精确定位)&quot;">​</a></h2><p>这是最基础的类型。</p><ul><li><strong>动作逻辑：</strong> 机器人必须到达目标点的<strong>物理坐标点</strong>，且轴的运动速度完全降为 0，确认到位后才执行下一条指令。</li><li><strong>路径特点：</strong> 动作会有明显的“停顿感”。</li><li><strong>适用场景：</strong> 需要极高位置精度的场合，如：装配、点焊、抓取工件的瞬间。</li></ul><h2 id="relative-相对百分比过渡" tabindex="-1">RELATIVE (相对百分比过渡) <a class="header-anchor" href="#relative-相对百分比过渡" aria-label="Permalink to &quot;RELATIVE (相对百分比过渡)&quot;">​</a></h2><ul><li><strong>概念</strong>：RELATIVE 是一种相对过渡（Relative/Blend Path）。</li><li><strong>特性</strong>：机器人不在目标点精确停下，而是在接近目标点时，根据设定的平滑距离参数（如 <code>[R, 100]</code>，即圆弧距离），平滑地转弯至下一个动作。</li><li><strong>特点</strong>： <ul><li><strong>运动</strong>：连续不间断，速度波动小。</li><li><strong>轨迹</strong>：经过一个弯角（圆弧过渡），平滑平滑，非直线。</li><li><strong>适用场景</strong>：轨迹涂胶、弧焊、连续码垛等需要高运动效率、连续运行的工序。</li></ul></li></ul><h2 id="absolute-绝对半径过渡" tabindex="-1">ABSOLUTE（绝对半径过渡） <a class="header-anchor" href="#absolute-绝对半径过渡" aria-label="Permalink to &quot;ABSOLUTE（绝对半径过渡）&quot;">​</a></h2><p>这是一种<strong>基于距离</strong>的平滑方式。</p><ul><li><strong>动作逻辑：</strong> 你需要设定一个具体的数值（例如 50mm）。当机器人进入距离目标点 50mm 的范围内时，就开始向下一个点转弯。</li><li><strong>路径特点：</strong> 机器人<strong>不会</strong>经过目标点的中心，而是切出一道弧线。数值越大，弧度越平滑，偏离目标点越远。</li><li><strong>适用场景：</strong> 涂胶、切割、或者单纯为了缩短节拍（Cycle Time）的中间过渡点。</li></ul><h2 id="总结对比" tabindex="-1">总结对比 <a class="header-anchor" href="#总结对比" aria-label="Permalink to &quot;总结对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>是否停顿</strong></th><th><strong>轨迹精度</strong></th><th><strong>运行效率</strong></th><th><strong>核心特征</strong></th></tr></thead><tbody><tr><td><strong>FINE</strong></td><td>是</td><td>最高</td><td>最低</td><td>必须完全停稳，点对点到位</td></tr><tr><td><strong>ABSOLUTE</strong></td><td>否</td><td>中等</td><td>高</td><td>按<strong>物理距离</strong>（mm）提前转弯</td></tr><tr><td><strong>RELATIVE</strong></td><td>否</td><td>较低</td><td>最高</td><td>按<strong>比例</strong>（%）提前转弯</td></tr><tr><td><strong>DEFAULT</strong></td><td>取决于设置</td><td>-</td><td>-</td><td></td></tr></tbody></table><p><img src="'+a+'" alt=""></p>',14)])])}const m=r(e,[["render",l]]);export{_ as __pageData,m as default};
